                for c in range(min(cols), max(cols) + 1):
                    out[r][c] = color

    # Sparse cells outside the horizontal bars mark vertical shafts. At each
    # shaft, horizontal bars project upward to the previous crossing; the
    # original shaft color continues below the lowest crossing.
    seeds = {}
    bar_set = set(bar_rows)
