        crossings = []
        for r in bar_rows:
            color = out[r][c]
            if color:
                crossings.append((r, color))
        prev = -1
        for r, color in crossings:
            for rr in range(prev + 1, r + 1):
                out[rr][c] = color
            prev = r
        if cells:
            # These marks are the continuation below the last horizontal bar.
            # Preserve their color and extend to the bottom edge from just
            # below the final crossing (or from their first mark if no crossing).
            lower = [(r, color) for r, color in cells if r > prev]
